//! Core geometric primitives: points, paths and the free functions that
//! operate on them (`Area`, `TranslatePath(s)`, `Bounds`, ...).
//!
//! Coordinates are 64-bit integers, mirroring `Clipper2Lib::Point64`.

use std::fmt;
use std::ops::{Add, Sub};

/// An integer 2D point (`Clipper2Lib::Point64`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    #[inline]
    pub const fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// Rounds a floating point pair to the nearest integer point, using
    /// round-half-away-from-zero (the behaviour of `std::llround`, which is
    /// what Clipper2 uses when it snaps intersections onto the integer grid).
    #[inline]
    pub fn from_f64(x: f64, y: f64) -> Self {
        Point64::new(round_half_away(x), round_half_away(y))
    }

    #[inline]
    pub fn as_f64(self) -> (f64, f64) {
        (self.x as f64, self.y as f64)
    }
}

impl Add for Point64 {
    type Output = Point64;
    #[inline]
    fn add(self, o: Point64) -> Point64 {
        Point64::new(self.x + o.x, self.y + o.y)
    }
}

impl Sub for Point64 {
    type Output = Point64;
    #[inline]
    fn sub(self, o: Point64) -> Point64 {
        Point64::new(self.x - o.x, self.y - o.y)
    }
}

impl fmt::Display for Point64 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{},{}", self.x, self.y)
    }
}

#[inline]
pub(crate) fn round_half_away(v: f64) -> i64 {
    // f64::round() already rounds half away from zero.
    v.round() as i64
}

/// A single closed (or open) polygon.
pub type Path64 = Vec<Point64>;
/// A collection of polygons.
pub type Paths64 = Vec<Path64>;

/// An axis aligned bounding box.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 { left, top, right, bottom }
    }

    /// The "invalid" rect Clipper2 returns for empty input: an inverted box.
    pub fn invalid() -> Self {
        Rect64::new(i64::MAX, i64::MAX, i64::MIN, i64::MIN)
    }

    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }

    pub fn width(&self) -> i64 {
        self.right - self.left
    }

    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }

    pub fn as_path(&self) -> Path64 {
        vec![
            Point64::new(self.left, self.top),
            Point64::new(self.right, self.top),
            Point64::new(self.right, self.bottom),
            Point64::new(self.left, self.bottom),
        ]
    }
}

/// Signed area of a closed path.
///
/// Uses the same accumulation order as Clipper2 so that the floating point
/// rounding matches: `sum over edges of (prev.y + curr.y) * (prev.x - curr.x)`,
/// halved. Counter-clockwise rings (in a y-up coordinate system) are positive.
pub fn area(path: &[Point64]) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    let mut prev = path[path.len() - 1];
    for &cur in path {
        a += (prev.y + cur.y) as f64 * (prev.x - cur.x) as f64;
        prev = cur;
    }
    a * 0.5
}

/// Sum of the signed areas of every path (holes, being clockwise, subtract).
pub fn area_paths(paths: &[Path64]) -> f64 {
    paths.iter().map(|p| area(p)).sum()
}

/// `true` when the path winds counter-clockwise (positive signed area).
pub fn is_positive(path: &[Point64]) -> bool {
    area(path) >= 0.0
}

/// Offsets every vertex of `path` by (`dx`, `dy`).
pub fn translate_path(path: &[Point64], dx: i64, dy: i64) -> Path64 {
    path.iter().map(|p| Point64::new(p.x + dx, p.y + dy)).collect()
}

/// Offsets every vertex of every path by (`dx`, `dy`).
pub fn translate_paths(paths: &[Path64], dx: i64, dy: i64) -> Paths64 {
    paths.iter().map(|p| translate_path(p, dx, dy)).collect()
}

/// Reverses the vertex order (and therefore the orientation) of a path.
pub fn reverse_path(path: &[Point64]) -> Path64 {
    let mut out = path.to_vec();
    out.reverse();
    out
}

pub fn reverse_paths(paths: &[Path64]) -> Paths64 {
    paths.iter().map(|p| reverse_path(p)).collect()
}

/// Bounding box of a set of paths.
pub fn bounds(paths: &[Path64]) -> Rect64 {
    let mut r = Rect64::invalid();
    for path in paths {
        for p in path {
            if p.x < r.left {
                r.left = p.x;
            }
            if p.x > r.right {
                r.right = p.x;
            }
            if p.y < r.top {
                r.top = p.y;
            }
            if p.y > r.bottom {
                r.bottom = p.y;
            }
        }
    }
    r
}

/// Drops repeated adjacent vertices (and a trailing vertex equal to the first).
pub fn strip_duplicates(path: &[Point64]) -> Path64 {
    let mut out: Path64 = Vec::with_capacity(path.len());
    for &p in path {
        if out.last() != Some(&p) {
            out.push(p);
        }
    }
    while out.len() > 1 && out.first() == out.last() {
        out.pop();
    }
    out
}

/// Removes vertices that lie exactly on the segment joining their neighbours.
pub fn strip_collinear(path: &[Point64]) -> Path64 {
    let src = strip_duplicates(path);
    let n = src.len();
    if n < 3 {
        return src;
    }
    let mut out: Path64 = Vec::with_capacity(n);
    for i in 0..n {
        let prev = src[(i + n - 1) % n];
        let cur = src[i];
        let next = src[(i + 1) % n];
        let cross = (cur.x as i128 - prev.x as i128) * (next.y as i128 - prev.y as i128)
            - (cur.y as i128 - prev.y as i128) * (next.x as i128 - prev.x as i128);
        if cross != 0 {
            out.push(cur);
        }
    }
    out
}

/// Winding-number point-in-polygon test for a single path.
pub fn point_in_path(path: &[Point64], pt: Point64) -> bool {
    let (px, py) = pt.as_f64();
    let mut w = 0i32;
    let n = path.len();
    if n < 3 {
        return false;
    }
    for i in 0..n {
        let a = path[i];
        let b = path[(i + 1) % n];
        w += crossing_delta(a, b, px, py);
    }
    w != 0
}

/// Contribution of the directed edge `a -> b` to the winding number of the
/// point (`px`, `py`), using a ray cast towards +x with the usual half-open
/// rule so that vertices are never counted twice.
#[inline]
pub(crate) fn crossing_delta(a: Point64, b: Point64, px: f64, py: f64) -> i32 {
    let (ax, ay) = a.as_f64();
    let (bx, by) = b.as_f64();
    if ay <= py {
        if by > py && is_left(ax, ay, bx, by, px, py) > 0.0 {
            return 1;
        }
    } else if by <= py && is_left(ax, ay, bx, by, px, py) < 0.0 {
        return -1;
    }
    0
}

/// > 0 when (px, py) lies left of the directed line a -> b.
#[inline]
pub(crate) fn is_left(ax: f64, ay: f64, bx: f64, by: f64, px: f64, py: f64) -> f64 {
    (bx - ax) * (py - ay) - (px - ax) * (by - ay)
}

