//! The boolean clipping engine.
//!
//! Rather than porting Clipper2's Vatti sweep-line, this is an independent
//! re-implementation of the same *semantics* built on a planar arrangement:
//!
//! 1. every input edge is cut at all of its intersections with every other
//!    edge, producing a set of sub-edges whose interiors are disjoint;
//! 2. each distinct sub-edge is classified by evaluating the subject and clip
//!    winding numbers immediately to its left and right — a sub-edge survives
//!    only when the boolean result differs across it, i.e. when it really is
//!    part of the result's boundary;
//! 3. surviving sub-edges are oriented so the filled region lies on their left
//!    and then chained into rings by always taking the sharpest clockwise turn,
//!    which yields minimal, non self-crossing contours.
//!
//! Outer contours therefore come out counter-clockwise (positive area) and
//! holes clockwise (negative area), matching Clipper2's output convention.

use std::collections::HashMap;

use super::core::{crossing_delta, is_left, strip_collinear, strip_duplicates, Path64, Paths64, Point64};

/// How the winding number of a region is turned into "filled / not filled".
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

/// The boolean operation to perform.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ClipType {
    NoClip,
    Intersection,
    Union,
    Difference,
    Xor,
}

/// Which operand a path belongs to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PathType {
    Subject,
    Clip,
}

#[inline]
fn is_filled(fill_rule: FillRule, w: i32) -> bool {
    match fill_rule {
        FillRule::EvenOdd => w % 2 != 0,
        FillRule::NonZero => w != 0,
        FillRule::Positive => w > 0,
        FillRule::Negative => w < 0,
    }
}

#[inline]
fn in_result(ct: ClipType, fill_rule: FillRule, w_subj: i32, w_clip: i32) -> bool {
    let s = is_filled(fill_rule, w_subj);
    let c = is_filled(fill_rule, w_clip);
    match ct {
        ClipType::NoClip => false,
        ClipType::Intersection => s && c,
        ClipType::Union => s || c,
        ClipType::Difference => s && !c,
        ClipType::Xor => s != c,
    }
}

#[derive(Clone, Copy)]
struct Segment {
    a: Point64,
    b: Point64,
    kind: PathType,
}

/// The clipping engine (`Clipper2Lib::Clipper64`).
#[derive(Clone, Debug, Default)]
pub struct Clipper64 {
    subjects: Paths64,
    clips: Paths64,
    preserve_collinear: bool,
}

impl Clipper64 {
    pub fn new() -> Self {
        Clipper64 { subjects: Vec::new(), clips: Vec::new(), preserve_collinear: true }
    }

    /// Clipper2 keeps collinear vertices by default; set to `false` to have
    /// redundant vertices removed from the result.
    pub fn set_preserve_collinear(&mut self, value: bool) -> &mut Self {
        self.preserve_collinear = value;
        self
    }

    pub fn add_subject(&mut self, paths: &[Path64]) -> &mut Self {
        self.subjects.extend(paths.iter().cloned());
        self
    }

    pub fn add_clip(&mut self, paths: &[Path64]) -> &mut Self {
        self.clips.extend(paths.iter().cloned());
        self
    }

    pub fn clear(&mut self) {
        self.subjects.clear();
        self.clips.clear();
    }

    /// Runs the boolean operation and returns the resulting closed paths.
    pub fn execute(&self, clip_type: ClipType, fill_rule: FillRule) -> Paths64 {
        let segments = self.collect_segments();
        if segments.is_empty() || clip_type == ClipType::NoClip {
            return Vec::new();
        }
        let sub_edges = split_all(&segments);
        let directed = classify(&sub_edges, &segments, clip_type, fill_rule);
        let rings = trace_rings(&directed);

        let mut out: Paths64 = Vec::with_capacity(rings.len());
        for ring in rings {
            let path = if self.preserve_collinear {
                strip_duplicates(&ring)
            } else {
                strip_collinear(&ring)
            };
            if path.len() >= 3 {
                out.push(path);
            }
        }
        out
    }

    fn collect_segments(&self) -> Vec<Segment> {
        let mut segs = Vec::new();
        push_path_segments(&mut segs, &self.subjects, PathType::Subject);
        push_path_segments(&mut segs, &self.clips, PathType::Clip);
        segs
    }
}

fn push_path_segments(out: &mut Vec<Segment>, paths: &[Path64], kind: PathType) {
    for path in paths {
        let pts = strip_duplicates(path);
        let n = pts.len();
        if n < 2 {
            continue;
        }
        for i in 0..n {
            let a = pts[i];
            let b = pts[(i + 1) % n];
            if a != b {
                out.push(Segment { a, b, kind });
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Step 1: cut every segment at every intersection.
// ---------------------------------------------------------------------------

#[inline]
fn cross(ax: i128, ay: i128, bx: i128, by: i128) -> i128 {
    ax * by - ay * bx
}

/// `true` when `num / den` lies within the closed unit interval.
#[inline]
fn in_unit_interval(num: i128, den: i128) -> bool {
    if den > 0 {
        num >= 0 && num <= den
    } else {
        num <= 0 && num >= den
    }
}

/// Squared-length-free ordering key of `pt` along the segment `a -> b`.
#[inline]
fn param_along(a: Point64, b: Point64, pt: Point64) -> i128 {
    let dx = b.x as i128 - a.x as i128;
    let dy = b.y as i128 - a.y as i128;
    (pt.x as i128 - a.x as i128) * dx + (pt.y as i128 - a.y as i128) * dy
}

fn on_segment(a: Point64, b: Point64, pt: Point64) -> bool {
    let t = param_along(a, b, pt);
    if t < 0 {
        return false;
    }
    let len2 = param_along(a, b, b);
    t <= len2
}

/// Records every point at which `s1` and `s2` meet.
fn intersect_segments(
    s1: &Segment,
    s2: &Segment,
    out1: &mut Vec<Point64>,
    out2: &mut Vec<Point64>,
) {
    let rx = s1.b.x as i128 - s1.a.x as i128;
    let ry = s1.b.y as i128 - s1.a.y as i128;
    let sx = s2.b.x as i128 - s2.a.x as i128;
    let sy = s2.b.y as i128 - s2.a.y as i128;
    let qpx = s2.a.x as i128 - s1.a.x as i128;
    let qpy = s2.a.y as i128 - s1.a.y as i128;

    let rxs = cross(rx, ry, sx, sy);
    if rxs == 0 {
        // Parallel; only collinear overlaps introduce split points.
        if cross(qpx, qpy, rx, ry) != 0 {
            return;
        }
        for pt in [s2.a, s2.b] {
            if on_segment(s1.a, s1.b, pt) {
                out1.push(pt);
            }
        }
        for pt in [s1.a, s1.b] {
            if on_segment(s2.a, s2.b, pt) {
                out2.push(pt);
            }
        }
        return;
    }

    let t_num = cross(qpx, qpy, sx, sy);
    let u_num = cross(qpx, qpy, rx, ry);
    if !in_unit_interval(t_num, rxs) || !in_unit_interval(u_num, rxs) {
        return;
    }

    // Snap the intersection onto the integer grid, exactly as Clipper2 does.
    let t = t_num as f64 / rxs as f64;
    let ip = Point64::from_f64(
        s1.a.x as f64 + t * rx as f64,
        s1.a.y as f64 + t * ry as f64,
    );
    out1.push(ip);
    out2.push(ip);
}

/// Splits every segment at its intersections and returns the distinct
/// undirected sub-edges, sorted for deterministic output.
fn split_all(segments: &[Segment]) -> Vec<(Point64, Point64)> {
    let n = segments.len();
    let mut splits: Vec<Vec<Point64>> = vec![Vec::new(); n];
    for i in 0..n {
        for j in (i + 1)..n {
            let (left, right) = splits.split_at_mut(j);
            intersect_segments(&segments[i], &segments[j], &mut left[i], &mut right[0]);
        }
    }

    let mut edges: Vec<(Point64, Point64)> = Vec::new();
    for (i, seg) in segments.iter().enumerate() {
        let mut pts: Vec<Point64> = Vec::with_capacity(splits[i].len() + 2);
        pts.push(seg.a);
        pts.append(&mut splits[i]);
        pts.push(seg.b);
        pts.sort_by(|p, q| {
            param_along(seg.a, seg.b, *p)
                .cmp(&param_along(seg.a, seg.b, *q))
                .then_with(|| p.cmp(q))
        });
        pts.dedup();
        for w in pts.windows(2) {
            let (p, q) = (w[0], w[1]);
            if p == q {
                continue;
            }
            edges.push(if p <= q { (p, q) } else { (q, p) });
        }
    }

    edges.sort();
    edges.dedup();
    edges
}

// ---------------------------------------------------------------------------
// Step 2: classify each sub-edge against the boolean result.
// ---------------------------------------------------------------------------

fn dist_point_segment(px: f64, py: f64, seg: &Segment) -> f64 {
    let (ax, ay) = seg.a.as_f64();
    let (bx, by) = seg.b.as_f64();
    let dx = bx - ax;
    let dy = by - ay;
    let len2 = dx * dx + dy * dy;
    let (cx, cy) = if len2 == 0.0 {
        (ax, ay)
    } else {
        let mut t = ((px - ax) * dx + (py - ay) * dy) / len2;
        if t < 0.0 {
            t = 0.0;
        } else if t > 1.0 {
            t = 1.0;
        }
        (ax + t * dx, ay + t * dy)
    };
    ((px - cx) * (px - cx) + (py - cy) * (py - cy)).sqrt()
}

/// Winding number of the operand `kind` around the probe point.
fn winding_at(segments: &[Segment], kind: PathType, px: f64, py: f64) -> i32 {
    let mut w = 0i32;
    for seg in segments {
        if seg.kind == kind {
            w += crossing_delta(seg.a, seg.b, px, py);
        }
    }
    w
}

/// Returns the sub-edges that belong to the result, directed so that the
/// filled region lies to their left.
fn classify(
    edges: &[(Point64, Point64)],
    segments: &[Segment],
    clip_type: ClipType,
    fill_rule: FillRule,
) -> Vec<(Point64, Point64)> {
    let mut kept = Vec::new();
    for &(p, q) in edges {
        let mx = (p.x as f64 + q.x as f64) * 0.5;
        let my = (p.y as f64 + q.y as f64) * 0.5;

        // Largest offset that is guaranteed to stay inside the two faces
        // adjacent to this sub-edge: half the distance to the nearest edge
        // that does not pass through the midpoint.
        let mut nearest = f64::INFINITY;
        for seg in segments {
            let d = dist_point_segment(mx, my, seg);
            if d > 1e-9 && d < nearest {
                nearest = d;
            }
        }
        let delta = if nearest.is_finite() { nearest * 0.5 } else { 1.0 };

        let dx = q.x as f64 - p.x as f64;
        let dy = q.y as f64 - p.y as f64;
        let len = (dx * dx + dy * dy).sqrt();
        if len == 0.0 {
            continue;
        }
        // Left-hand normal of p -> q.
        let nx = -dy / len * delta;
        let ny = dx / len * delta;

        let left = in_result(
            clip_type,
            fill_rule,
            winding_at(segments, PathType::Subject, mx + nx, my + ny),
            winding_at(segments, PathType::Clip, mx + nx, my + ny),
        );
        let right = in_result(
            clip_type,
            fill_rule,
            winding_at(segments, PathType::Subject, mx - nx, my - ny),
            winding_at(segments, PathType::Clip, mx - nx, my - ny),
        );

        if left && !right {
            kept.push((p, q));
        } else if right && !left {
            kept.push((q, p));
        }
    }
    kept
}

// ---------------------------------------------------------------------------
// Step 3: chain the surviving edges into closed rings.
// ---------------------------------------------------------------------------

/// Rotation, in (0, 2*PI], needed to sweep clockwise from `from` onto `to`.
fn clockwise_turn(from: (f64, f64), to: (f64, f64)) -> f64 {
    let tau = std::f64::consts::PI * 2.0;
    let mut ang = from.1.atan2(from.0) - to.1.atan2(to.0);
    while ang <= 0.0 {
        ang += tau;
    }
    while ang > tau {
        ang -= tau;
    }
    ang
}

fn trace_rings(edges: &[(Point64, Point64)]) -> Vec<Path64> {
    let mut outgoing: HashMap<Point64, Vec<usize>> = HashMap::new();
    for (i, &(from, _)) in edges.iter().enumerate() {
        outgoing.entry(from).or_default().push(i);
    }

    let mut used = vec![false; edges.len()];
    let mut rings: Vec<Path64> = Vec::new();

    for start in 0..edges.len() {
        if used[start] {
            continue;
        }
        let mut ring: Path64 = Vec::new();
        let mut cur = start;
        loop {
            used[cur] = true;
            let (u, v) = edges[cur];
            ring.push(u);

            let candidates = match outgoing.get(&v) {
                Some(c) => c,
                None => break,
            };
            // Hug the boundary: from the reversed incoming direction, take the
            // first outgoing edge found sweeping clockwise.
            let back = (u.x as f64 - v.x as f64, u.y as f64 - v.y as f64);
            let mut best: Option<usize> = None;
            let mut best_turn = f64::INFINITY;
            for &c in candidates {
                if used[c] {
                    continue;
                }
                let w = edges[c].1;
                let dir = (w.x as f64 - v.x as f64, w.y as f64 - v.y as f64);
                let turn = clockwise_turn(back, dir);
                if turn < best_turn {
                    best_turn = turn;
                    best = Some(c);
                }
            }
            match best {
                Some(next) => cur = next,
                None => break,
            }
        }
        if ring.len() >= 3 {
            rings.push(ring);
        }
    }
    rings
}

