//! Reproduces `std::ostream`'s default formatting of a `double`.
//!
//! `std::cout << x` uses `defaultfloat` with precision 6, which is `printf`'s
//! `%g` with precision 6: pick `%e` or `%f` based on the decimal exponent and
//! strip trailing zeros (there is no `#` flag).

/// Formats `value` exactly as `std::cout << value` would with default state.
pub fn fmt_double(value: f64) -> String {
    fmt_double_prec(value, 6)
}

/// `%g` with an explicit precision, as `std::cout` with `setprecision(p)`.
pub fn fmt_double_prec(value: f64, precision: usize) -> String {
    if value.is_nan() {
        // libstdc++ prints "-nan" for a negative-signed NaN.
        return if value.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if value.is_infinite() {
        return if value < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }

    let p = if precision == 0 { 1 } else { precision };

    // The exponent of the value *after* rounding to p significant digits, which
    // is what C's %g inspects when choosing a style.
    let sci = format!("{:.*e}", p - 1, value);
    let exp: i32 = match sci.rfind('e') {
        Some(i) => sci[i + 1..].parse().unwrap_or(0),
        None => 0,
    };

    if exp >= -4 && exp < p as i32 {
        let decimals = (p as i32 - 1 - exp).max(0) as usize;
        trim_zeros(&format!("{:.*}", decimals, value))
    } else {
        let (mantissa, _) = sci.split_at(sci.rfind('e').unwrap_or(sci.len()));
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", trim_zeros(mantissa), sign, exp.abs())
    }
}

/// Drops trailing fractional zeros, and the point itself if nothing follows.
fn trim_zeros(s: &str) -> String {
    if !s.contains('.') {
        return s.to_string();
    }
    let trimmed = s.trim_end_matches('0');
    trimmed.strip_suffix('.').unwrap_or(trimmed).to_string()
}

