// Rust port of tests/test6.cpp — six Clipper2 API calls: the union of several
// overlapping rectangles, its total area, and a translation of the result.

mod clipper2;

use clipper2::{area, fmt_double, translate_paths, union, FillRule, Path64, Paths64, Point64};

fn main() {
    // Accept (and ignore) the same command line arguments as the C++ binary.
    let _args: Vec<String> = std::env::args().collect();

    // 6个API：多个形状的并集
    let rect1: Path64 = vec![
        Point64::new(0, 0),
        Point64::new(50, 0),
        Point64::new(50, 50),
        Point64::new(0, 50),
    ];
    let rect2: Path64 = vec![
        Point64::new(25, 25),
        Point64::new(75, 25),
        Point64::new(75, 75),
        Point64::new(25, 75),
    ];
    let rect3: Path64 = vec![
        Point64::new(50, 50),
        Point64::new(100, 50),
        Point64::new(100, 100),
        Point64::new(50, 100),
    ];

    let subjects: Paths64 = vec![rect1, rect2, rect3];

    // 调用6个API：多个并集操作
    let union_all: Paths64 = union(&subjects, FillRule::NonZero);
    let mut total_area = 0.0f64;
    for path in &union_all {
        total_area += area(path);
    }

    // 平移并集结果
    let _translated: Paths64 = translate_paths(&union_all, 200, 200);

    println!("{}", fmt_double(total_area));
}

