// Independent validation of the clipper2 engine: compares the area of every
// boolean op against a brute-force cell count that never touches the engine.
#[path = "/output/clipper2/mod.rs"]
mod clipper2;

use clipper2::{area_paths, boolean_op, ClipType, FillRule, Path64, Paths64, Point64};

struct Lcg(u64);
impl Lcg {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        self.0 >> 11
    }
    fn range(&mut self, lo: i64, hi: i64) -> i64 {
        lo + (self.next() % ((hi - lo) as u64)) as i64
    }
}

#[derive(Clone, Copy)]
struct Rect {
    l: i64,
    t: i64,
    r: i64,
    b: i64,
    ccw: bool,
}

impl Rect {
    fn path(&self) -> Path64 {
        let p = vec![
            Point64::new(self.l, self.t),
            Point64::new(self.r, self.t),
            Point64::new(self.r, self.b),
            Point64::new(self.l, self.b),
        ];
        if self.ccw {
            p
        } else {
            let mut q = p;
            q.reverse();
            q
        }
    }
    // Winding contribution at a point strictly inside a unit cell.
    fn wind(&self, x: f64, y: f64) -> i32 {
        if x > self.l as f64 && x < self.r as f64 && y > self.t as f64 && y < self.b as f64 {
            if self.ccw {
                1
            } else {
                -1
            }
        } else {
            0
        }
    }
}

fn filled(fr: FillRule, w: i32) -> bool {
    match fr {
        FillRule::EvenOdd => w % 2 != 0,
        FillRule::NonZero => w != 0,
        FillRule::Positive => w > 0,
        FillRule::Negative => w < 0,
    }
}

fn expected(ct: ClipType, fr: FillRule, subj: &[Rect], clip: &[Rect]) -> f64 {
    let mut cells = 0i64;
    for i in -2..42 {
        for j in -2..42 {
            let (x, y) = (i as f64 + 0.5, j as f64 + 0.5);
            let ws: i32 = subj.iter().map(|r| r.wind(x, y)).sum();
            let wc: i32 = clip.iter().map(|r| r.wind(x, y)).sum();
            let (s, c) = (filled(fr, ws), filled(fr, wc));
            let inside = match ct {
                ClipType::Intersection => s && c,
                ClipType::Union => s || c,
                ClipType::Difference => s && !c,
                ClipType::Xor => s != c,
                ClipType::NoClip => false,
            };
            if inside {
                cells += 1;
            }
        }
    }
    cells as f64
}

fn main() {
    let mut rng = Lcg(0x5eed_1234);
    let ops = [ClipType::Union, ClipType::Intersection, ClipType::Difference, ClipType::Xor];
    let rules = [FillRule::NonZero, FillRule::EvenOdd, FillRule::Positive, FillRule::Negative];
    let mut failures = 0;
    let mut checked = 0;

    for trial in 0..400 {
        let ns = 1 + (rng.next() % 3) as usize;
        let nc = (rng.next() % 3) as usize;
        let mut mk = |rng: &mut Lcg| {
            let l = rng.range(0, 35);
            let t = rng.range(0, 35);
            Rect {
                l,
                t,
                r: l + rng.range(1, 15),
                b: t + rng.range(1, 15),
                ccw: rng.next() % 4 != 0,
            }
        };
        let subj: Vec<Rect> = (0..ns).map(|_| mk(&mut rng)).collect();
        let clip: Vec<Rect> = (0..nc).map(|_| mk(&mut rng)).collect();
        let sp: Paths64 = subj.iter().map(|r| r.path()).collect();
        let cp: Paths64 = clip.iter().map(|r| r.path()).collect();

        for &ct in &ops {
            for &fr in &rules {
                let got = area_paths(&boolean_op(ct, fr, &sp, &cp));
                let want = expected(ct, fr, &subj, &clip);
                checked += 1;
                if (got - want).abs() > 1e-9 {
                    failures += 1;
                    if failures < 8 {
                        println!(
                            "MISMATCH trial={} op={:?} rule={:?} got={} want={}\n  subj={:?}\n  clip={:?}",
                            trial,
                            ct,
                            fr,
                            got,
                            want,
                            subj.iter().map(|r| (r.l, r.t, r.r, r.b, r.ccw)).collect::<Vec<_>>(),
                            clip.iter().map(|r| (r.l, r.t, r.r, r.b, r.ccw)).collect::<Vec<_>>()
                        );
                    }
                }
            }
        }
    }
    println!("checked {} cases, {} failures", checked, failures);
}

