// Second validation pass: arbitrary (possibly self-intersecting) polygons with
// non-axis-aligned edges, checked against scanline integration of the boolean
// predicate. Coordinates are multiples of 1000 so that the engine's snapping of
// intersections onto the integer grid is negligible relative to the areas.
#[path = "/output/clipper2/mod.rs"]
mod clipper2;

use clipper2::{area_paths, boolean_op, ClipType, FillRule, Path64, Paths64, Point64};

struct Lcg(u64);
impl Lcg {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        self.0 >> 11
    }
    fn range(&mut self, lo: i64, hi: i64) -> i64 {
        lo + (self.next() % ((hi - lo) as u64)) as i64
    }
}

fn filled(fr: FillRule, w: i32) -> bool {
    match fr {
        FillRule::EvenOdd => w % 2 != 0,
        FillRule::NonZero => w != 0,
        FillRule::Positive => w > 0,
        FillRule::Negative => w < 0,
    }
}

fn predicate(ct: ClipType, fr: FillRule, ws: i32, wc: i32) -> bool {
    let (s, c) = (filled(fr, ws), filled(fr, wc));
    match ct {
        ClipType::Intersection => s && c,
        ClipType::Union => s || c,
        ClipType::Difference => s && !c,
        ClipType::Xor => s != c,
        ClipType::NoClip => false,
    }
}

const LO: f64 = -2000.0;
const HI: f64 = 32000.0;
const STEP: f64 = 10.0;

/// Exact 1-D measure of the filled set on the scanline `y`, integrated over y
/// with the midpoint rule.
fn expected(ct: ClipType, fr: FillRule, subj: &[Path64], clip: &[Path64]) -> f64 {
    let mut total = 0.0f64;
    let mut y = LO + STEP * 0.5;
    // (x, winding delta crossing left-to-right, is_subject)
    let mut xs: Vec<(f64, i32, bool)> = Vec::new();
    while y < HI {
        xs.clear();
        for (paths, is_subj) in [(subj, true), (clip, false)] {
            for path in paths {
                let n = path.len();
                for i in 0..n {
                    let a = path[i];
                    let b = path[(i + 1) % n];
                    let (ay, by) = (a.y as f64, b.y as f64);
                    if (ay <= y) == (by <= y) {
                        continue;
                    }
                    let t = (y - ay) / (by - ay);
                    let x = a.x as f64 + t * (b.x as f64 - a.x as f64);
                    // Crossing an upward edge rightwards decreases the winding.
                    xs.push((x, if by > ay { -1 } else { 1 }, is_subj));
                }
            }
        }
        xs.sort_by(|p, q| p.0.partial_cmp(&q.0).unwrap());
        let (mut ws, mut wc) = (0i32, 0i32);
        for k in 0..xs.len() {
            let (x, d, is_subj) = xs[k];
            if is_subj {
                ws += d;
            } else {
                wc += d;
            }
            if k + 1 < xs.len() && predicate(ct, fr, ws, wc) {
                total += (xs[k + 1].0 - x) * STEP;
            }
        }
        y += STEP;
    }
    total
}

fn main() {
    let mut rng = Lcg(0xC1_1PPE_R2u64 as u64);
    let ops = [ClipType::Union, ClipType::Intersection, ClipType::Difference, ClipType::Xor];
    let rules = [FillRule::NonZero, FillRule::EvenOdd, FillRule::Positive, FillRule::Negative];
    let (mut failures, mut checked) = (0, 0);
    let mut worst: f64 = 0.0;

    for trial in 0..60 {
        let mut mk = |rng: &mut Lcg| -> Path64 {
            let nv = rng.range(3, 7) as usize;
            (0..nv)
                .map(|_| Point64::new(rng.range(0, 31) * 1000, rng.range(0, 31) * 1000))
                .collect()
        };
        let sp: Paths64 = (0..1 + rng.next() % 2).map(|_| mk(&mut rng)).collect();
        let cp: Paths64 = (0..rng.next() % 2).map(|_| mk(&mut rng)).collect();

        for &ct in &ops {
            for &fr in &rules {
                let got = area_paths(&boolean_op(ct, fr, &sp, &cp));
                let want = expected(ct, fr, &sp, &cp);
                checked += 1;
                let err = (got - want).abs();
                let tol = 1.0e-3 * (want.abs().max(1.0e6));
                if err > worst {
                    worst = err;
                }
                if err > tol {
                    failures += 1;
                    if failures <= 5 {
                        println!(
                            "MISMATCH trial={} op={:?} rule={:?} got={} want={} err={}\n  subj={:?}\n  clip={:?}",
                            trial, ct, fr, got, want, err, sp, cp
                        );
                    }
                }
            }
        }
    }
    println!("checked {} cases, {} failures, worst abs err {:.1} (areas ~1e8)", checked, failures, worst);
}

