200	fn intersect_segments(
201	    s1: &Segment,
202	    s2: &Segment,
203	    out1: &mut Vec<Point64>,
204	    out2: &mut Vec<Point64>,
205	) {
206	    let rx = s1.b.x as i128 - s1.a.x as i128;
207	    let ry = s1.b.y as i128 - s1.a.y as i128;
208	    let sx = s2.b.x as i128 - s2.a.x as i128;
209	    let sy = s2.b.y as i128 - s2.a.y as i128;
210	    let qpx = s2.a.x as i128 - s1.a.x as i128;
211	    let qpy = s2.a.y as i128 - s1.a.y as i128;
212	
213	    let rxs = cross(rx, ry, sx, sy);
214	    if rxs == 0 {
215	        // Parallel; only collinear overlaps introduce split points.
216	        if cross(qpx, qpy, rx, ry) != 0 {
217	            return;
218	        }
219	        for pt in [s2.a, s2.b] {
220	            if on_segment(s1.a, s1.b, pt) {
221	                out1.push(pt);
222	            }
223	        }
224	        for pt in [s1.a, s1.b] {
225	            if on_segment(s2.a, s2.b, pt) {
226	                out2.push(pt);
227	            }
228	        }
229	        return;
230	    }
231	
232	    let t_num = cross(qpx, qpy, sx, sy);
233	    let u_num = cross(qpx, qpy, rx, ry);
234	    if !in_unit_interval(t_num, rxs) || !in_unit_interval(u_num, rxs) {
235	        return;
236	    }
237	
238	    // Snap the intersection onto the integer grid, exactly as Clipper2 does.
239	    let t = t_num as f64 / rxs as f64;
