/// Splits every segment at its intersections. The result is the *arrangement*:
/// the same closed loops as the input, but re-expressed as directed sub-edges
/// whose interiors are pairwise disjoint. Duplicates (collinear overlaps) are
/// kept, since each still contributes to the winding number.
fn split_all(segments: &[Segment]) -> Vec<Segment> {
    let n = segments.len();
    let mut splits: Vec<Vec<Point64>> = vec![Vec::new(); n];
    for i in 0..n {
        for j in (i + 1)..n {
            let (left, right) = splits.split_at_mut(j);
            intersect_segments(&segments[i], &segments[j], &mut left[i], &mut right[0]);
        }
    }

    let mut sub_edges: Vec<Segment> = Vec::new();
    for (i, seg) in segments.iter().enumerate() {
        // Sort only the interior points: `a` must stay first and `b` last, so
        // that the chain still joins up with the neighbouring segments even
        // when snapping nudges a point past an endpoint.
        let mut mid = std::mem::take(&mut splits[i]);
        mid.sort_by(|p, q| {
            param_along(seg.a, seg.b, *p)
                .cmp(&param_along(seg.a, seg.b, *q))
                .then_with(|| p.cmp(q))
        });
        let mut pts: Vec<Point64> = Vec::with_capacity(mid.len() + 2);
        pts.push(seg.a);
        pts.extend(mid);
        pts.push(seg.b);
        pts.dedup();
        for w in pts.windows(2) {
            if w[0] != w[1] {
                sub_edges.push(Segment { a: w[0], b: w[1], kind: seg.kind });
            }
        }
    }
    sub_edges
}

/// The distinct undirected edges of the arrangement, sorted so that the traced
/// output is deterministic.
fn distinct_edges(sub_edges: &[Segment]) -> Vec<(Point64, Point64)> {
    let mut edges: Vec<(Point64, Point64)> = sub_edges
        .iter()
        .map(|s| if s.a <= s.b { (s.a, s.b) } else { (s.b, s.a) })
        .collect();
    edges.sort();
    edges.dedup();
    edges
}

