// Focused check on the thin-sliver cases: is the residual error grid-snapping
// quantization (shrinks relative to area as coordinates are scaled up) or an
// algorithmic error (stays constant)?
#[path = "/output/clipper2/mod.rs"]
mod clipper2;

use clipper2::{area_paths, boolean_op, ClipType, FillRule, Path64, Paths64, Point64};

fn filled(fr: FillRule, w: i32) -> bool {
    match fr {
        FillRule::EvenOdd => w % 2 != 0,
        FillRule::NonZero => w != 0,
        FillRule::Positive => w > 0,
        FillRule::Negative => w < 0,
    }
}

fn predicate(ct: ClipType, fr: FillRule, ws: i32, wc: i32) -> bool {
    let (s, c) = (filled(fr, ws), filled(fr, wc));
    match ct {
        ClipType::Intersection => s && c,
        ClipType::Union => s || c,
        ClipType::Difference => s && !c,
        ClipType::Xor => s != c,
        ClipType::NoClip => false,
    }
}

fn expected(ct: ClipType, fr: FillRule, subj: &[Path64], clip: &[Path64], step: f64) -> f64 {
    let (mut lo, mut hi) = (f64::INFINITY, f64::NEG_INFINITY);
    for p in subj.iter().chain(clip.iter()) {
        for v in p {
            lo = lo.min(v.y as f64);
            hi = hi.max(v.y as f64);
        }
    }
    let mut total = 0.0f64;
    let mut y = lo + step * 0.5;
    let mut xs: Vec<(f64, i32, bool)> = Vec::new();
    while y < hi {
        xs.clear();
        for (paths, is_subj) in [(subj, true), (clip, false)] {
            for path in paths {
                let n = path.len();
                for i in 0..n {
                    let (a, b) = (path[i], path[(i + 1) % n]);
                    let (ay, by) = (a.y as f64, b.y as f64);
                    if (ay <= y) == (by <= y) {
                        continue;
                    }
                    let t = (y - ay) / (by - ay);
                    xs.push((
                        a.x as f64 + t * (b.x as f64 - a.x as f64),
                        if by > ay { -1 } else { 1 },
                        is_subj,
                    ));
                }
            }
        }
        xs.sort_by(|p, q| p.0.partial_cmp(&q.0).unwrap());
        let (mut ws, mut wc) = (0i32, 0i32);
        for k in 0..xs.len() {
            let (x, d, is_subj) = xs[k];
            if is_subj {
                ws += d;
            } else {
                wc += d;
            }
            if k + 1 < xs.len() && predicate(ct, fr, ws, wc) {
                total += (xs[k + 1].0 - x) * step;
            }
        }
        y += step;
    }
    total
}

fn scaled(p: &[Path64], s: i64) -> Paths64 {
    p.iter()
        .map(|path| path.iter().map(|v| Point64::new(v.x * s, v.y * s)).collect())
        .collect()
}

fn main() {
    let subj: Paths64 = vec![vec![
        Point64::new(0, 12000),
        Point64::new(26000, 16000),
        Point64::new(25000, 16000),
    ]];
    let clip: Paths64 = vec![vec![
        Point64::new(22000, 12000),
        Point64::new(7000, 9000),
        Point64::new(2000, 29000),
        Point64::new(1000, 11000),
        Point64::new(2000, 27000),
        Point64::new(14000, 12000),
    ]];

    println!("{:>6}  {:>18}  {:>18}  {:>12}", "scale", "engine", "reference", "rel err");
    for &s in &[1i64, 10, 100, 1000] {
        let sp = scaled(&subj, s);
        let cp = scaled(&clip, s);
        // Reference step fixed in *original* units so its own discretization
        // error stays at a constant relative level across scales.
        let step = 0.02 * s as f64;
        for &(ct, fr) in &[
            (ClipType::Intersection, FillRule::EvenOdd),
            (ClipType::Difference, FillRule::Positive),
        ] {
            let got = area_paths(&boolean_op(ct, fr, &sp, &cp));
            let want = expected(ct, fr, &sp, &cp, step);
            println!(
                "{:>6}  {:>18.1}  {:>18.1}  {:>12.3e}   {:?}/{:?}",
                s,
                got,
                want,
                (got - want).abs() / want.abs(),
                ct,
                fr
            );
        }
    }
}

